function validate([s, shifts]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 100000) return 's needs 1 to 100000 characters.';
  if (!/^[a-z]+$/.test(s)) return 's may only contain lowercase letters.';
  if (!Array.isArray(shifts) || shifts.length !== s.length) return 'shifts must have one entry per character of s.';
  if (shifts.some(v => !Number.isInteger(v) || v < 0 || v > 1000000000)) return 'Each shift is an integer from 0 to 10^9.';
  return null;
}

