function shiftingLetters(s, shifts) {
  const codes = [...s].map(ch => ch.charCodeAt(0) - 97);
  for (let i = 0; i < shifts.length; i++) {
    const step = shifts[i] % 26;
    for (let j = 0; j <= i; j++) codes[j] = (codes[j] + step) % 26;
  }
  return codes.map(c => String.fromCharCode(97 + c)).join('');
}

