function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? 2000 : pick(1, 8);
  const alphabet = size === 'large' || rand() < 0.5 ? 26 : pick(1, 4);
  const start = alphabet === 26 ? 0 : pick(0, 26 - alphabet);
  let s = '';
  for (let i = 0; i < n; i++) s += String.fromCharCode(97 + start + pick(0, alphabet - 1));
  const shifts = [];
  for (let i = 0; i < n; i++) {
    const r = rand();
    if (r < 0.15) shifts.push(0);
    else if (r < 0.3) shifts.push(1000000000 - pick(0, 30));
    else if (r < 0.45) shifts.push(26 * pick(1, 5));
    else shifts.push(size === 'large' ? pick(0, 1000000000) : pick(0, 60));
  }
  return [s, shifts];
}
